model:
rachana: 1
sutra: variant-call
version: 1
description: 
match: { kind: variant-call, priority: 10 }
title: { pill: "Genomics · Variant call", id: "$.CALL_ID" }
strip:
  - { label: "Call id", bind: "$.CALL_ID" }
  - { label: "Sample id", bind: "link($.SAMPLE_ID, 'study-sample')" }
  - { label: "Variant id", bind: "link($.VARIANT_ID, 'study-variant')" }
  - { label: "Genotype", bind: "$.GENOTYPE" }
  - { label: "Vaf", bind: "$.VAF", emphasis: true }
panels:
  - id: record
    kind: kv
    title: "Variant call"
    columns:
      - { label: "Call id", bind: "$.CALL_ID" }
      - { label: "Sample id", bind: "link($.SAMPLE_ID, 'study-sample')" }
      - { label: "Variant id", bind: "link($.VARIANT_ID, 'study-variant')" }
      - { label: "Gene", bind: "link($.GENE, 'study-gene')" }
      - { label: "Genotype", bind: "$.GENOTYPE" }
      - { label: "Vaf", bind: "$.VAF" }
      - { label: "Depth", bind: "$.DEPTH", fmt: "amount0" }
keys: { F9: "raw" }
